Get-VIEvent -Start (Get-Date).AddHours(-12) -MaxSamples 10000 | Where-Object {$_.GetType().Name -match "Dvs.*Sync" -or $_.FullFormattedMessage -like "*Distributed Switch*configuration*host*differed*"} |Select CreatedTime,@{N="Type";E={$_.GetType().Name}},@{N="DVS";E={$_.Dvs.Name}},@{N="Host";E={if ($_.HostOutOfSync) {$_.HostOutOfSync.OutOfSyncHost.Name} elseif ($_.HostBackInSync) {$_.HostBackInSync.Name} elseif ($_.Host) {$_.Host.Name}}},@{N="ConfigParams";E={if ($_.HostOutOfSync) {$_.HostOutOfSync.ConfigParamters -join "; "}}},FullFormattedMessage